import base64
import hashlib
import os
import subprocess
import time
import zlib
from tkinter import Tk, filedialog

# the holy dll
DATA = {'orig_size': 1467904, 'orig_sha256': '72b0c26053c37edd3435def461e9027cd6ffad12032db2fd0b32c256fdbee6b9', 'patched_sha256': '761ddd0b6dae7f73bccd9c4236713dd7ed4aa32714102a5c7b0acff6764ae8c6', 'edits': [(310, '06', '07'), (333, 'ea', 'ec'), (385, 'b0', 'c0'), (392, '000000', '924117'), (792, '00000000', '2e667073'), (800, '00', '93'), (805, '0000', 'b016'), (809, '00', '02'), (813, '0000', '6616'), (828, '00', '20'), (831, '00', 'e0'), (197806, 'be3affff', '4e9f1300')], 'tail': 'eNqbk/CCAQiieid1A6kGKwb+1hgg4xgTI1g8orcBxA2AcSwCfvz/L9B6gL/FDCgAFo3s7XQHUoFwNQJwNUJIamb5v/wf+P9C8xGWxLkvvs16/f9wWkFxaV5OfnK2XkpODgOQF5+Zl1nCMAroCQByIjNr', 'dll': ''}

print("super hexagon fps unlocker")
print("1) install")
print("2) uninstall")
choice = ""
while choice not in ("1", "2"):
    choice = input("> ").strip()

root = Tk()
root.withdraw()
exe = filedialog.askopenfilename(title="pick SuperHexagon.exe", filetypes=[("SuperHexagon.exe", "SuperHexagon.exe")])
root.destroy()
if not exe:
    print("no file picked")
    input("press enter to close")
    raise SystemExit

folder = os.path.dirname(exe)
data = bytearray(open(exe, "rb").read())
h = hashlib.sha256(data).hexdigest()
if h != DATA["orig_sha256"] and h != DATA["patched_sha256"]:
    print("invalid exe")
    input("press enter to close")
    raise SystemExit

if choice == "1":
    fps = ""
    while not (fps.isdigit() and (int(fps) == 0 or 60 < int(fps) <= 1000)):
        if fps:
            print("0 or 61 to 1000 pls")
        fps = input("fps limit (0 is for uncapped): ").strip()
    show = ""
    while show not in ("y", "n"):
        show = input("show fps counter? (y/n): ").strip().lower()
    if h == DATA["orig_sha256"]:
        for off, old, new in DATA["edits"]:
            data[off:off + len(new) // 2] = bytes.fromhex(new)
        data += zlib.decompress(base64.b64decode(DATA["tail"]))
elif h == DATA["patched_sha256"]:
    for off, old, new in DATA["edits"]:
        data[off:off + len(old) // 2] = bytes.fromhex(old)
    del data[DATA["orig_size"]:]

# the game locks the exe and dll while its open
try:
    open(exe, "r+b").close()
except PermissionError:
    subprocess.run(["taskkill", "/f", "/im", os.path.basename(exe)], capture_output=True)
    print("game was running, closed it")
    time.sleep(1)

if choice == "1":
    open(os.path.join(folder, "fpsunlock.dll"), "wb").write(zlib.decompress(base64.b64decode(DATA["dll"])))
    open(os.path.join(folder, "fpsunlock.ini"), "w").write("cap=%d\nshow_fps=%d\n" % (int(fps), show == "y"))
    open(exe, "wb").write(data)
    print("installed")
    print("you can change the config in fpsunlock.ini")
else:
    if h == DATA["patched_sha256"]:
        open(exe, "wb").write(data)
        print("uninstalled")
    else:
        print("this exe is not patched")
    for name in ("fpsunlock.dll", "fpsunlock.ini"):
        if os.path.exists(os.path.join(folder, name)):
            os.remove(os.path.join(folder, name))

input("press enter to close")
